  7	function renderKnowledge(app) {
  8	  showLoading(app);
  9	
 10	  /* ── Confidence bucket thresholds ────────────────────────── */
 11	  var CONFIDENCE_HIGH_MIN   = 68;   /* 68–100 → High  */
 12	  var CONFIDENCE_MEDIUM_MIN = 34;   /* 34–67  → Medium */
 13	  /* 0–33 → Low */
 14	
 15	  /* ── View state ──────────────────────────────────────────── */
 16	  var allInsights        = [];
 17	  var activeTab          = 'global';   /* 'global' | 'repository' */
 18	  var filterCategory     = '';
 19	  var filterRepository   = '';
 20	  var filterQuery        = '';
 21	  var editingId       = null;       /* numeric id of card in edit mode */
 22	  var confirmDeleteId = null;       /* numeric id of card in delete-confirm mode */
 23	  var movingId        = null;       /* numeric id of card in move mode */
 24	
 25	  /* ── formatConfidence ────────────────────────────────────── */
 26	  function formatConfidence(value) {
 27	    var pct = Math.round(value * 100);
 28	    var label;
 29	    if (pct >= CONFIDENCE_HIGH_MIN) {
 30	      label = 'High';
 31	    } else if (pct >= CONFIDENCE_MEDIUM_MIN) {
 32	      label = 'Medium';
 33	    } else {
 34	      label = 'Low';
 35	    }
 36	    return pct + '% (' + label + ')';
 37	  }
 38	
 39	  /* ── applyFilters ────────────────────────────────────────── */
 40	  function applyFilters() {
 41	    var scopeValue = activeTab === 'global' ? 'global' : 'repository';
 42	    return allInsights.filter(function (ins) {
 43	      if (ins.scope !== scopeValue) return false;
 44	      if (filterCategory && ins.category !== filterCategory) return false;
 45	      if (activeTab === 'repository' && filterRepository && ins.repository_name !== filterRepository) return false;
 46	      if (filterQuery) {
 47	        var q = filterQuery.toLowerCase();
 48	        var titleMatch    = ins.title   && ins.title.toLowerCase().indexOf(q) !== -1;
 49	        var contentMatch  = ins.content && ins.content.toLowerCase().indexOf(q) !== -1;
 50	        var tagsMatch     = ins.tags    && ins.tags.some(function (t) { return t.toLowerCase().indexOf(q) !== -1; });
 51	        if (!titleMatch && !contentMatch && !tagsMatch) return false;
 52	      }
 53	      return true;
 54	    });
 55	  }
 56	
 57	  /* ── getDistinctValues ───────────────────────────────────── */
 58	  /* Returns { categories: string[], repositories: string[] } — both arrays are
 59	     sorted alphabetically and contain only distinct non-empty values from
 60	     the provided insights array. */
 61	  function getDistinctValues(insights) {
 62	    var categories   = [];
 63	    var repositories = [];
 64	    insights.forEach(function (ins) {
 65	      if (ins.category        && categories.indexOf(ins.category)               === -1) categories.push(ins.category);
 66	      if (ins.repository_name && repositories.indexOf(ins.repository_name)      === -1) repositories.push(ins.repository_name);
 67	    });
 68	    categories.sort();
 69	    repositories.sort();
 70	    return { categories: categories, repositories: repositories };
 71	  }
