140	        return '<div class="card" data-id="' + id + '">' +
141	          '<form id="kn-edit-form-' + id + '">' +
142	            '<div class="form-group">' +
143	              '<label class="form-label">Title</label>' +
144	              '<input id="kn-edit-title-' + id + '" class="form-control" type="text" value="' + escapeHtml(ins.title || '') + '">' +
145	            '</div>' +
146	            '<div class="form-group">' +
147	              '<label class="form-label">Content</label>' +
148	              '<textarea id="kn-edit-content-' + id + '" class="form-control" rows="6">' + escapeHtml(ins.content || '') + '</textarea>' +
149	            '</div>' +
150	            '<div class="form-group">' +
151	              '<label class="form-label">Category</label>' +
152	              '<input id="kn-edit-category-' + id + '" class="form-control" type="text" value="' + escapeHtml(ins.category || '') + '">' +
153	            '</div>' +
154	            '<div class="form-group">' +
155	              '<label class="form-label">Tags (comma-separated)</label>' +
156	              '<input id="kn-edit-tags-' + id + '" class="form-control" type="text" value="' + escapeHtml(tagsValue) + '">' +
157	            '</div>' +
158	            '<div class="form-group">' +
159	              '<label class="form-label">Confidence: <span id="kn-conf-label-' + id + '">' + escapeHtml(confPct) + '</span></label>' +
160	              '<input id="kn-edit-conf-' + id + '" class="form-control" type="range" min="0" max="1" step="0.01" value="' + (ins.confidence != null ? ins.confidence : 0) + '">' +
161	            '</div>' +
162	            '<div class="knowledge-actions">' +
163	              '<button type="submit" class="btn btn-primary btn-sm">Save</button>' +
164	              '<button type="button" class="btn btn-sm" data-action="cancel-edit" data-id="' + id + '">Cancel</button>' +
165	            '</div>' +
166	            '<div id="kn-edit-msg-' + id + '"></div>' +
167	          '</form>' +
168	        '</div>';
169	      }
170	
171	      /* ── Action buttons ── */
172	      var deleteHtml;
173	      if (isConfirm) {
174	        deleteHtml =
175	          '<span>Delete this entry?</span>' +
176	          '<button class="btn btn-danger btn-sm" data-action="confirm-delete" data-id="' + id + '" data-scope="' + escapeHtml(ins.scope) + '" data-repository="' + escapeHtml(ins.repository_name || '') + '">Confirm</button>' +
177	          '<button class="btn btn-sm" data-action="cancel-delete" data-id="' + id + '">Cancel</button>';
178	      } else {
179	        deleteHtml = '<button class="btn btn-danger btn-sm" data-action="delete" data-id="' + id + '">Delete</button>';
180	      }
181	
182	      var promoteHtml = !isGlobal
183	        ? '<button class="btn btn-sm" data-action="promote" data-id="' + id + '" data-scope="' + escapeHtml(ins.scope) + '" data-repository="' + escapeHtml(ins.repository_name || '') + '">Promote to Global</button>'
184	        : '';
185	
186	      var moveHtml;
187	      if (isMoving) {
188	        moveHtml =
189	          '<span class="knowledge-move-input">' +
190	            '<input id="kn-move-repo-' + id + '" class="form-control form-control-sm" type="text" placeholder="target-repository-name">' +
191	            '<button class="btn btn-primary btn-sm" data-action="confirm-move" data-id="' + id + '" data-scope="' + escapeHtml(ins.scope) + '" data-repository="' + escapeHtml(ins.repository_name || '') + '">Confirm</button>' +
192	            '<button class="btn btn-sm" data-action="cancel-move" data-id="' + id + '">Cancel</button>' +
193	          '</span>';
194	      } else {
195	        moveHtml = '<button class="btn btn-sm" data-action="move" data-id="' + id + '">Move to Repository</button>';
196	      }
197	
198	      var originPlanHtml = ins.origin_plan
199	        ? '<a href="#/projects/' + encodeURIComponent(ins.origin_plan) + '" style="font-size:12px">Origin: ' + escapeHtml(ins.origin_plan) + '</a>'
200	        : '';
201	
202	      return '<div class="card" data-id="' + id + '">' +
203	        '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:6px">' +
204	          '<span class="' + scopeBadgeClass + '">' + scopeLabel + '</span>' +
205	          (ins.category ? '<span class="category-pill">' + escapeHtml(ins.category) + '</span>' : '') +
206	          (ins.repository_name ? '<span class="text-muted" style="font-size:12px">' + escapeHtml(ins.repository_name) + '</span>' : '') +
207	          (originPlanHtml ? originPlanHtml : '') +
208	        '</div>' +
209	        '<h3 style="margin:0 0 6px 0;font-size:15px">' + escapeHtml(ins.title || '(no title)') + '</h3>' +
210	        (tagsHtml ? '<div style="margin-bottom:6px">' + tagsHtml + '</div>' : '') +
211	        (preview ? '<p style="margin:0 0 6px 0;color:var(--color-text-muted);font-size:13px">' + escapeHtml(preview) + '</p>' : '') +
212	        '<div style="display:flex;align-items:center;gap:16px;font-size:12px;color:var(--color-text-muted);margin-bottom:4px">' +
213	          '<span class="confidence-label">Confidence: ' + escapeHtml(ins.confidence != null ? formatConfidence(ins.confidence) : '—') + '</span>' +
214	          (ins.source ? '<span>Source: ' + escapeHtml(ins.source) + '</span>' : '') +
215	        '</div>' +
216	        '<div style="font-size:11px;color:var(--color-text-muted);margin-bottom:8px">' +
217	          'Created: ' + escapeHtml(formatDate(ins.created_at)) +
218	          ' &nbsp;·&nbsp; Updated: ' + escapeHtml(formatDate(ins.updated_at)) +
219	        '</div>' +
220	        supersededHtml +
221	        '<div class="knowledge-actions">' +
222	          '<button class="btn btn-sm" data-action="edit" data-id="' + id + '">Edit</button>' +
223	          deleteHtml +
224	          promoteHtml +
225	          moveHtml +
226	        '</div>' +
227	      '</div>';
228	    }).join('');
229	  }
