231	  /* ── render ──────────────────────────────────────────────── */
232	  function render(insights) {
233	    allInsights = insights;
234	
235	    var vals         = getDistinctValues(insights);
236	    var categories   = vals.categories;
237	    var repositories = vals.repositories;
238	
239	    var filtered = applyFilters();
240	
241	    app.innerHTML =
242	      '<div class="page-header"><h1>Knowledge</h1></div>' +
243	      '<div class="knowledge-tabs">' +
244	        '<button class="knowledge-tab' + (activeTab === 'global' ? ' active' : '') + '" data-tab="global">Global</button>' +
245	        '<button class="knowledge-tab' + (activeTab === 'repository' ? ' active' : '') + '" data-tab="repository">Repository</button>' +
246	      '</div>' +
247	      '<div class="filter-bar" id="kn-filter-bar">' +
248	        buildFilterBarHtml(categories, repositories) +
249	      '</div>' +
250	      '<div id="knowledge-list">' + buildKnowledgeHtml(filtered) + '</div>';

251	
252	    wireEvents();
253	    wireRangeSliders();
254	  }
