256	  /* ── renderFilterBar ─── rebuild the filter bar only ─────────
257	   *
258	   * Rebuilds #kn-filter-bar and re-wires its event handlers.
259	   * Called when activeTab changes because only then does the bar layout
260	   * change (repository dropdown appears / disappears).
261	   * NOT called on every keystroke or card action — that was the root
262	   * cause of the focus-theft issue resolved here.
263	   */
264	  function renderFilterBar() {
265	    var vals = getDistinctValues(allInsights);
266	    var filterBarEl = document.getElementById('kn-filter-bar');
267	    if (filterBarEl) {
268	      filterBarEl.innerHTML = buildFilterBarHtml(vals.categories, vals.repositories);
269	      wireFilterBarEvents(filterBarEl);
270	    }
271	  }
272	
273	  /* ── renderList ─── partial re-render of card list only ────────
274	   *
275	   * Rebuilds #knowledge-list with the current filtered card set.
276	   * Does NOT touch the filter bar. Call renderFilterBar() explicitly
277	   * when activeTab changes and the bar layout needs to change.
278	   */
279	  function renderList() {
280	    var filtered = applyFilters();
281	    var listEl = document.getElementById('knowledge-list');
282	    if (listEl) {
283	      listEl.innerHTML = buildKnowledgeHtml(filtered);
284	    }
285	    wireRangeSliders();
286	  }
