288	  /* ── wireRangeSliders ─── live confidence label updates ─────── */
289	  function wireRangeSliders() {
290	    var inputs = document.querySelectorAll('input[type="range"][id^="kn-edit-conf-"]');
291	    inputs.forEach(function (input) {
292	      var idStr = input.id.replace('kn-edit-conf-', '');
293	      input.addEventListener('input', function () {
294	        var labelEl = document.getElementById('kn-conf-label-' + idStr);
295	        if (labelEl) labelEl.textContent = formatConfidence(parseFloat(this.value));
296	      });
297	    });
298	  }
299	
300	  /* ── wireFilterBarEvents ─── attach change/input to filter controls ── */
301	  function wireFilterBarEvents(filterBarEl) {
302	    var catEl  = filterBarEl.querySelector('#kn-category');
303	    var repoEl = filterBarEl.querySelector('#kn-repository');
304	    var qEl    = filterBarEl.querySelector('#kn-query');
305	
306	    if (catEl) {
307	      catEl.addEventListener('change', function () {
308	        filterCategory = this.value;
309	        renderList();
310	      });
311	    }
312	    if (repoEl) {
313	      repoEl.addEventListener('change', function () {
314	        filterRepository = this.value;
315	        renderList();
316	      });
317	    }
318	    if (qEl) {
319	      qEl.addEventListener('input', function () {
320	        filterQuery = this.value;
321	        renderList();
322	      });
323	    }
324	  }
