326	  /* ── wireEvents ──────────────────────────────────────────── */
327	  function wireEvents() {
328	    /* Tab bar */
329	    var tabButtons = document.querySelectorAll('.knowledge-tab');
330	    tabButtons.forEach(function (btn) {
331	      btn.addEventListener('click', function () {
332	        var newTab = this.getAttribute('data-tab');
333	        if (newTab === activeTab) return;
334	        activeTab          = newTab;
335	        filterCategory     = '';
336	        filterRepository   = '';
337	        filterQuery        = '';
338	        editingId       = null;
339	        confirmDeleteId = null;
340	        movingId        = null;
341	
342	        /* Update active class */
343	        tabButtons.forEach(function (b) {
344	          b.classList.toggle('active', b.getAttribute('data-tab') === activeTab);
345	        });
346	
347	        /* Tab change alters the filter bar layout (repository dropdown appears/
348	           disappears), so rebuild the bar first, then re-render the card list. */
349	        renderFilterBar();
350	        renderList();
351	      });
352	    });
353	
354	    /* Wire filter bar */
355	    var filterBarEl = document.getElementById('kn-filter-bar');
356	    if (filterBarEl) wireFilterBarEvents(filterBarEl);
357	
358	    /* Event delegation for card actions */
359	    var listEl = document.getElementById('knowledge-list');
360	    if (!listEl) return;
361	
362	    listEl.addEventListener('click', function (e) {
363	      var btn = e.target.closest('[data-action]');
364	      if (!btn) return;
365	
366	      var action = btn.getAttribute('data-action');
367	      var rawId  = btn.getAttribute('data-id');
368	      var id     = parseInt(rawId, 10);
369	
370	      if (action === 'edit') {
371	        editingId       = id;
372	        confirmDeleteId = null;
373	        movingId        = null;
374	        renderList();
375	        return;
376	      }
377	
378	      if (action === 'cancel-edit') {
379	        editingId = null;
380	        renderList();
381	        return;
382	      }
383	
384	      if (action === 'delete') {
385	        confirmDeleteId = id;
386	        editingId       = null;
387	        movingId        = null;
388	        renderList();
389	        return;
390	      }
391	
392	      if (action === 'cancel-delete') {
393	        confirmDeleteId = null;
394	        renderList();
395	        return;
396	      }
397	
398	      if (action === 'move') {
399	        movingId        = id;
400	        editingId       = null;

401	        confirmDeleteId = null;
402	        renderList();
403	        return;
404	      }
405	
406	      if (action === 'cancel-move') {
407	        movingId = null;
408	        renderList();
409	        return;
410	      }
411	
412	      /* ── Confirm delete ── */
413	      if (action === 'confirm-delete') {
414	        var delScope = btn.getAttribute('data-scope');
415	        var delRepo  = btn.getAttribute('data-repository') || null;
416	        API.deleteKnowledge(id, delScope, delRepo).then(function () {
417	          allInsights = allInsights.filter(function (ins) { return ins.id !== id; });
418	          confirmDeleteId = null;
419	          renderList();
420	        }).catch(function (err) {
421	          showError(app, 'Delete failed: ' + (err.message || String(err)));
422	        });
423	        return;
424	      }
425	
426	      /* ── Promote to Global ── */
427	      if (action === 'promote') {
428	        var promScope = btn.getAttribute('data-scope');
429	        var promRepo  = btn.getAttribute('data-repository') || null;
430	        API.promoteKnowledge(id, promScope, promRepo).then(function (newInsight) {
431	          allInsights = allInsights.filter(function (ins) { return ins.id !== id; });
432	          allInsights.push(newInsight);
433	          renderList();
434	        }).catch(function (err) {
435	          showError(app, 'Promote failed: ' + (err.message || String(err)));
436	        });
437	        return;
438	      }
439	
440	      /* ── Confirm move ── */
441	      if (action === 'confirm-move') {
442	        var moveScope      = btn.getAttribute('data-scope');
443	        var moveRepo       = btn.getAttribute('data-repository') || null;
444	        var targetInput    = document.getElementById('kn-move-repo-' + id);
445	        var targetRepoName = targetInput ? targetInput.value.trim() : '';
446	        if (!targetRepoName) return;
447	        API.moveKnowledge(id, moveScope, moveRepo, targetRepoName).then(function (newInsight) {
448	          allInsights = allInsights.filter(function (ins) { return ins.id !== id; });
449	          allInsights.push(newInsight);
450	          movingId = null;
451	          renderList();
452	        }).catch(function (err) {
453	          showError(app, 'Move failed: ' + (err.message || String(err)));
454	        });
455	        return;
456	      }
457	    });
458	
459	    /* Edit form submit — uses event delegation on the list container */
460	    listEl.addEventListener('submit', function (e) {
461	      var form = e.target.closest('form[id^="kn-edit-form-"]');
462	      if (!form) return;
463	      e.preventDefault();
464	
465	      var formId = form.id.replace('kn-edit-form-', '');
466	      var eid    = parseInt(formId, 10);
467	
468	      /* Find insight to get scope/repository_name */
469	      var original = allInsights.find(function (ins) { return ins.id === eid; });
470	      if (!original) return;
471	
472	      var titleEl    = document.getElementById('kn-edit-title-'   + eid);
473	      var contentEl  = document.getElementById('kn-edit-content-' + eid);
474	      var categoryEl = document.getElementById('kn-edit-category-'+ eid);
475	      var tagsEl     = document.getElementById('kn-edit-tags-'    + eid);
476	      var confEl     = document.getElementById('kn-edit-conf-'    + eid);
477	      var msgEl      = document.getElementById('kn-edit-msg-'     + eid);
478	
479	      var rawTags = tagsEl ? tagsEl.value : '';
480	      var tags    = rawTags.split(',').map(function (t) { return t.trim(); }).filter(Boolean);
481	
482	      var updateData = {
483	        title:      titleEl    ? titleEl.value    : original.title,
484	        content:    contentEl  ? contentEl.value  : original.content,
485	        category:   categoryEl ? categoryEl.value : original.category,
486	        tags:       tags,
487	        confidence: confEl     ? parseFloat(confEl.value) : original.confidence,
488	      };
489	
490	      API.updateKnowledge(eid, original.scope, original.repository_name || null, updateData)
491	        .then(function (updated) {
492	          allInsights = allInsights.map(function (ins) {
493	            return ins.id === eid ? updated : ins;
494	          });
495	          editingId = null;
496	          renderList();
497	        })
498	        .catch(function (err) {
499	          /* Intentional: inline error preserves form state so the user does not lose
500	             edits on a transient save failure. All destructive actions (delete/promote/move)
501	             use showError(app, ...) because they navigate away or remove the card. */
502	          if (msgEl) msgEl.innerHTML = '<p class="error-banner">Save failed: ' + escapeHtml(err.message || String(err)) + '</p>';
503	        });
504	    });
505	  }
